SELECT ROUND(SUM(amount) / COUNT(DISTINCT order_id), 2) AS avg_order_value
FROM payments
WHERE paid_at >= '2026-07-01' AND paid_at < '2026-08-01';

SELECT ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM payments), 2) AS pct
FROM payments
WHERE method = '银联';

SELECT ROUND(SUM(item_count) / COUNT(*), 2) AS items_per_order
FROM orders
WHERE created_at >= '2026-06-01' AND created_at < '2026-07-01';
